from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit
from pathlib import Path
import hashlib, json, re

base = 'https://www.drivendata.org/competitions/'
root = Path('products/services/public-data-prize-trial')
source = root / 'raw/drivendata-competitions.html'
raw = source.read_bytes()
assert hashlib.sha256(raw).hexdigest() == '79bfdb1daceaf5dd2de6f9a4e7cdde32b295fa8e76f7480e688758e63f5ca7fd'

class CompetitionLinks(HTMLParser):
    def __init__(self):
        super().__init__()
        self.links = {}
        self.current = None
        self.label = []

    def handle_starttag(self, tag, attrs):
        if tag == 'a':
            url = urlsplit(urljoin(base, dict(attrs).get('href') or ''))
            if url.scheme == 'https' and url.netloc == 'www.drivendata.org' and re.fullmatch(r'/competitions/\d+(?:/[^/]+)?/?', url.path):
                self.current = 'https://www.drivendata.org' + url.path.rstrip('/') + '/'
                self.label = []

    def handle_data(self, data):
        if self.current:
            self.label.append(data)

    def handle_endtag(self, tag):
        if tag == 'a' and self.current:
            label = ' '.join(' '.join(self.label).split())
            if label or self.current not in self.links:
                self.links[self.current] = label
            self.current = None

parser = CompetitionLinks()
parser.feed(raw.decode('utf-8'))
result = {'source': base, 'source_sha256': hashlib.sha256(raw).hexdigest(), 'use': 'Navigation only. Original rules must establish status, eligibility and prize.', 'links': [{'url': url, 'label': label} for url, label in parser.links.items()]}
output = root / 'director-index-navigation.json'
output.parent.mkdir(parents=True, exist_ok=True)
output.write_text(json.dumps(result, indent=2) + '\n', encoding='utf-8')
assert json.loads(output.read_text(encoding='utf-8')) == result
print(json.dumps({'output': str(output), 'link_count': len(parser.links), 'first_links': result['links'][:8]}))
